003901-1e6a229e2d15?auto=format&fit=crop&w=1400&q=85","inStock":true,"skuSuffix":"BRS"}],"options":[],"option_group_label":null,"materials":["Extruded & CNC-Turned 6061 Aluminum","Optical Borosilicate Micro-Prism Diffuser","3.2kg Cast Iron & Brass Base Anchor"],"highlights":["Museum-Grade CRI 98.4 / R9 > 96 Spectral Accuracy","Stepless Dual-Ring Rotary Encoder for Lux & Kelvin","Ambient Radar Presence Sensor for Automatic Wake/Sleep"],"specifications":[{"group":"Acoustics & Electronics","label":"Color Rendering Index","value":"CRI 98.4 (R9 > 96 Full-Spectrum SunLike LED Array)"},{"group":"Acoustics & Electronics","label":"Color Temperature Range","value":"2,400K (Candlelight) – 5,600K (North Daylight)"},{"group":"Dimensions & Weight","label":"Reach & Height","value":"780mm Horizontal Span × 540mm Vertical Clearance // 4.1 kg"},{"group":"Connectivity & Power","label":"Power Delivery","value":"Braided 2.4m Fabric Cable + Integrated 45W USB-C Base Passthrough Port"}],"story_blocks":[{"id":"sb-03-1","eyebrow":"01 // CIRCADIAN PRECISION","title":"Zero Screen Glare. Zero Flicker.","description":"Engineered with an asymmetric optical cut-off, Solis floods your desk in 1,200 lux of high-CRI illumination without casting a single reflection onto studio displays.","image":"https://images.unsplash.com/photo-1513506003901-1e6a229e2d15?auto=format&fit=crop&w=1400&q=85","imageAlt":"Solis desk illumination","layout":"split-left","metrics":[{"label":"Spectral Accuracy","value":"98.4","unit":"CRI"},{"label":"Peak Illuminance","value":"1,200","unit":"Lux"},{"label":"Rated Lifespan","value":"65k","unit":"Hrs"}]}],"faqs":[{"question":"What is the rated lifespan of the optical LED array?","answer":"The passive aluminum heatsink chassis maintains junction temperatures below 48°C, yielding an L90 lifespan exceeding 65,000 hours."},{"question":"Can the base be replaced with a desk-edge clamp?","answer":"Yes. Every Solis unit includes both the 3.2kg freestanding architectural base and a CNC-milled billet C-clamp for desks up to 65mm thick."}],"shipping_estimate":"Demo only — no courier booking or fulfillment service is connected.","warranty_years":5,"seo_title":null,"seo_description":null,"canonical_path":null,"status":"active","created_at":"2026-06-12T10:00:00Z","updated_at":"2026-09-18T10:00:00Z"},{"id":"prod-04","slug":"kinetic-65-field-keyboard","sku":"NR-04-KIN","model_number":"NR-04 // KINETIC-65","name":"Kinetic-65 Mechanical Instrument","subtitle":"Gasket-Mounted Machined Aluminum & Brass Keyboard","short_description":"A 2.6kg solid billet mechanical typing instrument with custom Hall-effect magnetic switches, brass acoustic weight, and precision rotary encoder.","editorial_description":"Designed for writers, engineers, and architects who spend ten hours a day in dialogue with text. The Kinetic-65 isolates its internal switch plate on sixteen silicone poron gaskets, producing a deep, muted marimba-like acoustic profile.","category_id":"cat-input","price":520,"compare_at_price":580,"currency":"USD","stock_status":"in_stock","inventory_count":34,"badge":"bestseller","badge_label":"Signature Instrument","featured":true,"is_spotlight":false,"is_new_arrival":false,"release_year":2026,"designed_in":"Tokyo","primary_image":"https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=1400&q=85","secondary_image":"https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=1400&q=85","gallery":[{"id":"gal-04-1","url":"https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=1400&q=85","alt":"Kinetic-65 Mechanical Keyboard top view","caption":"Fig 01. Double-shot PBT keycaps with micro-textured matte surface."},{"id":"gal-04-2","url":"https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=1400&q=85","alt":"Kinetic-65 switch and keycap profile","caption":"Fig 02. Custom lubricated tactile and linear switch options."}],"colors":[{"id":"col-obsidian-04","