& Styluses"],"specifications":[{"group":"Dimensions & Weight","label":"External Dimensions","value":"1,160 × 240 × 112 mm // 5.8 kg"},{"group":"Architecture & Materials","label":"Load Capacity","value":"45 kg Static Load (Zero Central Deflection)"},{"group":"In The Box","label":"Hardware Included","value":"Plinth Deck, 2x Anodized Uprights, Wool Valet Tray, CNC Hex Driver"}],"story_blocks":[{"id":"sb-05-1","eyebrow":"01 // SPATIAL ORDER","title":"Two Levels of Architectural Calm","description":"By elevating displays to natural optical height and creating a shadowed sanctuary below for input instruments, Plinth restores visual stillness to the studio table.","image":"https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=1400&q=85","imageAlt":"Plinth Modular Desk Shelf","layout":"split-left"}],"faqs":[{"question":"Does the Plinth require tools to assemble?","answer":"Everything required is included in the box, including a custom CNC-turned hex driver and four stainless steel M6 fasteners."},{"question":"Will a 16-inch MacBook Pro fit inside the lower recess?","answer":"Yes. The central span offers 780mm of horizontal clearance and 74mm of vertical clearance beneath the valet drawer."}],"shipping_estimate":"Demo only — no courier booking or fulfillment service is connected.","warranty_years":10,"seo_title":null,"seo_description":null,"canonical_path":null,"status":"active","created_at":"2026-04-11T10:00:00Z","updated_at":"2026-09-01T10:00:00Z"},{"id":"prod-06","slug":"chronos-e-ink-horology","sku":"NR-06-CHR","model_number":"NR-06 // CHRONOS","name":"Chronos E-Ink Environmental Clock","subtitle":"Silent Ambient Horology & Air Quality Instrument","short_description":"High-contrast Carta 1300 E-Ink display framed in brushed titanium. Monitors CO2, barometric pressure, humidity, and time in complete silence.","editorial_description":"Chronos replaces glowing bedside and studio screens with the calm permanence of ink on paper. Updated once per minute with zero blue-light emission, it also tracks indoor CO2 and VOC levels using Swiss Sensirion sensors.","category_id":"cat-smart","price":340,"compare_at_price":null,"currency":"USD","stock_status":"in_stock","inventory_count":22,"badge":"new_release","badge_label":"New Instrument","featured":true,"is_spotlight":false,"is_new_arrival":true,"release_year":2026,"designed_in":"Zurich","primary_image":"https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=1400&q=85","secondary_image":"https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?auto=format&fit=crop&w=1400&q=85","gallery":[{"id":"gal-06-1","url":"https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=1400&q=85","alt":"Chronos E-Ink Instrument","caption":"Fig 01. Anti-glare etched mineral glass over 300 PPI E-Ink."},{"id":"gal-06-2","url":"https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?auto=format&fit=crop&w=1400&q=85","alt":"Chronos profile detail","caption":"Fig 02. Grade 5 Titanium bezel."}],"colors":[{"id":"col-titanium-06","name":"Raw Titanium","hex":"#A6A29A","finish":"Brushed Grade 5 Titanium","image":"https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=1400&q=85","secondaryImage":"https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?auto=format&fit=crop&w=1400&q=85","inStock":true,"skuSuffix":"TIT"},{"id":"col-obsidian-06","name":"Obsidian","hex":"#141413","finish":"DLC Coated Matte Carbon","image":"https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?auto=format&fit=crop&w=1400&q=85","secondaryImage":"https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=1400&q=85","inStock":true,"skuSuffix":"OBS"}],"options":[],"option_group_label":null,"materials":["Grade 5 Titanium Unibody Frame","Micro-Etched Anti-Glare Sapphire Crystal","Swiss Sensirion NDIR CO2 & Barometric Array"],"highlights":["300 PPI Carta 1300 E-Ink Display (Zero Blue Light)","9-