-- journal_articles (4 rows)
insert into public."journal_articles" ("id", "slug", "issue_number", "category", "title", "subtitle", "excerpt", "cover_image", "author_name", "author_role", "published_at", "reading_time_minutes", "featured", "related_product_ids", "content", "status")
select "id", "slug", "issue_number", "category", "title", "subtitle", "excerpt", "cover_image", "author_name", "author_role", "published_at", "reading_time_minutes", "featured", "related_product_ids", "content", "status"
from jsonb_populate_recordset(null::public."journal_articles", $noire_seed$[{"id":"art-01","slug":"the-weight-of-silence-machining-solid-aluminum","issue_number":"ISSUE 14 // MATERIAL STUDY","category":"Material Study","title":"The Weight of Silence: Why We Machine Speakers from Solid 6061 Billet","subtitle":"Inside our Zurich metallurgy workshop where a 14-kilogram aluminum block becomes an acoustic monolith.","excerpt":"Conventional speaker enclosures rely on glued MDF panels or injection-molded polymers that flex under low-frequency pressure. We took a radically different path.","cover_image":"https://images.unsplash.com/photo-1545454675-3531b543be5d?auto=format&fit=crop&w=1400&q=85","author_name":"Søren Lindqvist","author_role":"Head of Industrial Design, Zurich","published_at":"2026-09-18T09:00:00Z","reading_time_minutes":6,"featured":true,"related_product_ids":["prod-02","prod-01"],"content":["True acoustic transparency begins with what you do not hear: the enclosure itself. When a loudspeaker cabinet vibrates, it introduces secondary phase smearing that clouds transient detail.","By 5-axis CNC milling the Monolith One from a single forging of 6061-T6 aerospace aluminum, internal standing waves are dissipated across an integrated sinusoidal rib matrix.","Each chassis undergoes a 90-minute glass-bead blasting cycle before receiving a 45-micron Type III hard-anodized finish that resists oxidation for decades."],"status":"active"},{"id":"art-02","slug":"circadian-optics-sculpting-natural-light","issue_number":"ISSUE 13 // ARCHITECTURE","category":"Architecture","title":"Circadian Optics: Sculpting Glare-Free Illumination for Deep Work","subtitle":"How optical waveguides and CRI 98+ phosphor arrays transform nocturnal architecture studios.","excerpt":"Artificial light often flattens physical textures and fatigues the optic nerve. In designing Solis, we studied northern skylights.","cover_image":"https://images.unsplash.com/photo-1513506003901-1e6a229e2d15?auto=format&fit=crop&w=1400&q=85","author_name":"Elena Vance-Kuroda","author_role":"Principal Optical Engineer","published_at":"2026-08-29T09:00:00Z","reading_time_minutes":5,"featured":true,"related_product_ids":["prod-03","prod-09"],"content":["A luminaire should illuminate the work surface while remaining optically invisible to the eye. Using a micro-prismatic borosilicate diffuser, Solis casts a razor-defined 110cm pool of warm light with zero lateral glare."],"status":"active"},{"id":"art-03","slug":"tactile-permanence-in-an-era-of-glass-screens","issue_number":"ISSUE 12 // MONOGRAPH","category":"Monograph","title":"Tactile Permanence in an Era of Capacitive Glass","subtitle":"Why physical knurling, weighted brass detents, and mechanical switches restore human agency.","excerpt":"As interfaces retreat behind flat panes of glass, our fingers are starved of mechanical feedback. Here is how we engineer tactile certainty.","cover_image":"https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=1400&q=85","author_name":"Kenji Takahashi","author_role":"Lead Mechanical Architect, Tokyo","published_at":"2026-08-04T09:00:00Z","reading_time_minutes":7,"featured":true,"related_product_ids":["prod-04","prod-10"],"content":["When you rotate the brass volume encoder on the Kinetic-65, a custom magnetic Hall-effect indexing ring provides 72 distinct micro-detents per revolution—with zero mechanical wear."],"status":"active"},{"id":"art-04","slug":"planar-magnetic-physics-two-micron-diaphragm","issue_number":"ISSUE 11 // ACOUSTIC ENGINEERING","category":"Acoustic Engineering","title":"Planar Magnetic Physics: Suspending a Two-Micron Film in a 1.4-Tesla Field","subtitle":"How ultra-low-mass voice coils etched onto biaxially oriented film eliminate cone breakup and phase distortion.","excerpt":"In dynamic headphones, a voice coil drives only the center of a stiff dome. Our planar transducers apply electromagnetic force uniformly across 94% of the radiating surface.","cover_image":"https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=1400&q=85","author_name":"Dr. Lukas Meyer","author_role":"Chief Acoustic Physicist, Zurich","published_at":"2026-07-12T09:00:00Z","reading_time_minutes":8,"featured":false,"related_product_ids":["prod-01","prod-11"],"content":["Because electromagnetic force is distributed across the entire surface of our 2-micron diaphragm, transient edges launch as a coherent planar wavefront with less than 0.04% total harmonic distortion."],"status":"active"}]$noire_seed$::jsonb)
on conflict ("id") do update set "slug" = excluded."slug", "issue_number" = excluded."issue_number", "category" = excluded."category", "title" = excluded."title", "subtitle" = excluded."subtitle", "excerpt" = excluded."excerpt", "cover_image" = excluded."cover_image", "author_name" = excluded."author_name", "author_role" = excluded."author_role", "published_at" = excluded."published_at", "reading_time_minutes" = excluded."reading_time_minutes", "featured" = excluded."featured", "related_product_ids" = excluded."related_product_ids", "content" = excluded."content", "status" = excluded."status";

